package com.example.uniroom;
import android.os.*; import android.content.*; import android.widget.*; import androidx.appcompat.app.AppCompatActivity; import com.example.uniroom.model.Models.*; import com.example.uniroom.network.*; import retrofit2.*;
public class LoginActivity extends AppCompatActivity{
 EditText u,p; protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_login);u=findViewById(R.id.username);p=findViewById(R.id.password);findViewById(R.id.register).setOnClickListener(v->startActivity(new Intent(this,RegisterActivity.class)));findViewById(R.id.login).setOnClickListener(v->go());}
 void go(){if(u.getText().toString().trim().isEmpty()){u.setError("Required");return;}if(p.getText().toString().isEmpty()){p.setError("Required");return;}Client.api().login(new LoginRequest(u.getText().toString().trim(),p.getText().toString())).enqueue(new Callback<ApiResponse>(){public void onResponse(Call<ApiResponse> c,Response<ApiResponse> r){if(r.isSuccessful()&&r.body()!=null&&r.body().success){new Session(LoginActivity.this).save(r.body().user);startActivity(new Intent(LoginActivity.this,DashboardActivity.class));finish();}else Toast.makeText(LoginActivity.this,r.body()!=null?r.body().message:"Login failed",Toast.LENGTH_LONG).show();}public void onFailure(Call<ApiResponse> c,Throwable t){Toast.makeText(LoginActivity.this,"API connection failed",Toast.LENGTH_LONG).show();}});}
}
